CREATE TABLE "core_tenant" ("tenant_id" VARCHAR NOT NULL,"tenant_name" VARCHAR NOT NULL,"report_timezone" VARCHAR NOT NULL,"base_currency" VARCHAR NOT NULL,PRIMARY KEY ("tenant_id"));

CREATE TABLE "core_vehicle" ("tenant_id" VARCHAR NOT NULL,"vehicle_id" VARCHAR NOT NULL,"vin_raw" VARCHAR,"vin" VARCHAR,"vehicle_class" VARCHAR NOT NULL,"fuel_type" VARCHAR NOT NULL,PRIMARY KEY ("tenant_id","vehicle_id"));

CREATE TABLE "core_device" ("tenant_id" VARCHAR NOT NULL,"device_id" VARCHAR NOT NULL,"device_model" VARCHAR NOT NULL,PRIMARY KEY ("tenant_id","device_id"));

CREATE TABLE "core_vehicle_device_assignment" ("tenant_id" VARCHAR NOT NULL,"assignment_id" VARCHAR NOT NULL,"vehicle_id" VARCHAR NOT NULL,"device_id" VARCHAR NOT NULL,"valid_from" TIMESTAMPTZ NOT NULL,"valid_to" TIMESTAMPTZ,"known_from" TIMESTAMPTZ NOT NULL,"known_to" TIMESTAMPTZ,"valid_to_state" VARCHAR NOT NULL,"known_to_state" VARCHAR NOT NULL,"resolution_status" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,PRIMARY KEY ("tenant_id","assignment_id"));

CREATE TABLE "eta_trip" ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"registered_at" TIMESTAMPTZ NOT NULL,PRIMARY KEY ("tenant_id","trip_id"));

CREATE TABLE "eta_facility_version" ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"facility_version_id" VARCHAR NOT NULL,"facility_id" VARCHAR NOT NULL,"timezone" VARCHAR NOT NULL,"arrival_definition" VARCHAR NOT NULL,"latitude_deg" DOUBLE NOT NULL,"longitude_deg" DOUBLE NOT NULL,"valid_from" TIMESTAMPTZ NOT NULL,"valid_to" TIMESTAMPTZ,"known_from" TIMESTAMPTZ NOT NULL,"known_to" TIMESTAMPTZ,PRIMARY KEY ("tenant_id","facility_version_id"));

CREATE TABLE "eta_route_version" ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"route_version_id" VARCHAR NOT NULL,"route_id" VARCHAR NOT NULL,"origin_facility_version_id" VARCHAR NOT NULL,"destination_facility_version_id" VARCHAR NOT NULL,"planned_distance_km" DECIMAL(12,3) NOT NULL,"valid_from" TIMESTAMPTZ NOT NULL,"valid_to" TIMESTAMPTZ,"known_at" TIMESTAMPTZ NOT NULL,PRIMARY KEY ("tenant_id","route_version_id"));

CREATE TABLE "eta_trip_plan_version" ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"trip_version_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"vehicle_id" VARCHAR NOT NULL,"route_version_id" VARCHAR NOT NULL,"planned_departure_at" TIMESTAMPTZ NOT NULL,"origin_facility_version_id" VARCHAR NOT NULL,"destination_facility_version_id" VARCHAR NOT NULL,"plan_known_at" TIMESTAMPTZ NOT NULL,"supersedes_trip_version_id" VARCHAR,PRIMARY KEY ("tenant_id","trip_version_id"));

CREATE TABLE "eta_promise_version" ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"promise_version_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"window_start_at" TIMESTAMPTZ NOT NULL,"window_end_at" TIMESTAMPTZ NOT NULL,"known_at" TIMESTAMPTZ NOT NULL,"supersedes_promise_version_id" VARCHAR,"change_reason" VARCHAR NOT NULL,PRIMARY KEY ("tenant_id","promise_version_id"));

CREATE TABLE "eta_trip_event" ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"trip_event_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"event_type" VARCHAR NOT NULL,"occurred_at" TIMESTAMPTZ NOT NULL,"available_at" TIMESTAMPTZ NOT NULL,"trip_status" VARCHAR NOT NULL,PRIMARY KEY ("tenant_id","trip_event_id"));

CREATE TABLE "eta_trip_outcome" ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"outcome_version_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"actual_arrival_time" TIMESTAMPTZ,"service_start_time" TIMESTAMPTZ,"delivery_completed_time" TIMESTAMPTZ,"cancellation_time" TIMESTAMPTZ,"label_available_time" TIMESTAMPTZ NOT NULL,"label_status" VARCHAR NOT NULL,"arrival_evidence_ref" VARCHAR,"arrival_time_precision" VARCHAR NOT NULL,"reviewer_id" VARCHAR,"cancellation_reason" VARCHAR,"followup_through" TIMESTAMPTZ NOT NULL,"followup_end_reason" VARCHAR NOT NULL,"revision_reason" VARCHAR,"supersedes_outcome_version_id" VARCHAR,PRIMARY KEY ("tenant_id","outcome_version_id"));

CREATE TABLE "telemetry_event" ("tenant_id" VARCHAR NOT NULL,"canonical_event_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"event_type" VARCHAR,"gnss_valid" VARCHAR,"event_time" TIMESTAMPTZ,"latitude_deg" DOUBLE,"longitude_deg" DOUBLE,"device_id" VARCHAR NOT NULL,"vehicle_id" VARCHAR,"source_event_id" VARCHAR NOT NULL,"source_system_id" VARCHAR NOT NULL,"record_revision" VARCHAR NOT NULL,"raw_record_id" VARCHAR,"mapping_version" VARCHAR NOT NULL,"boot_session_id" VARCHAR NOT NULL,"available_time" TIMESTAMPTZ NOT NULL,"vehicle_speed_kmh" DECIMAL(9,3),"gnss_speed_kmh" DECIMAL(9,3),"vehicle_speed_origin" VARCHAR,"engine_distance_km" DECIMAL(18,6),"engine_runtime_seconds" DECIMAL(18,3),"engine_rpm" DECIMAL(10,3),"counter_epoch_id" VARCHAR,PRIMARY KEY ("tenant_id","canonical_event_id"));

CREATE TABLE "provenance_record" ("provenance_id" VARCHAR NOT NULL,"source_system_id" VARCHAR NOT NULL,"source_record_id" VARCHAR NOT NULL,"record_version" VARCHAR NOT NULL,"record_state" VARCHAR NOT NULL,"event_time" TIMESTAMPTZ,"available_time" TIMESTAMPTZ,"retrieved_at" TIMESTAMPTZ NOT NULL,"extract_as_of" TIMESTAMPTZ NOT NULL,"raw_record_reference" VARCHAR NOT NULL,"origin_type" VARCHAR NOT NULL,"source_dataset_id" VARCHAR NOT NULL,"synthetic_scenario_id" VARCHAR,"value_states" JSON NOT NULL,"source_timezone" VARCHAR,"source_utc_offset_minutes" INTEGER,"tenant_id" VARCHAR,"field_origins" JSON NOT NULL,"availability_basis" VARCHAR NOT NULL,"availability_evidence" VARCHAR,"canonical_table" VARCHAR NOT NULL,"canonical_record_key" JSON NOT NULL,"parent_provenance_ids" JSON NOT NULL,PRIMARY KEY ("provenance_id"));

CREATE TABLE "eta_snapshot" ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"trip_version_id" VARCHAR NOT NULL,"promise_version_id" VARCHAR NOT NULL,"route_version_id" VARCHAR NOT NULL,"vehicle_id" VARCHAR NOT NULL,"device_id" VARCHAR,"selected_position_event_id" VARCHAR,"snapshot_time" TIMESTAMPTZ NOT NULL,"trip_status_as_of" VARCHAR NOT NULL,"latitude_deg" DOUBLE,"longitude_deg" DOUBLE,"last_position_time" TIMESTAMPTZ,"position_available_at" TIMESTAMPTZ,"position_validity" VARCHAR NOT NULL,"gnss_speed_kmh" DECIMAL(9,3),"position_age_seconds" BIGINT,"remaining_distance_km" DECIMAL(12,3),"departure_time_bucket" VARCHAR NOT NULL,"elapsed_trip_seconds" BIGINT,"feature_definition_version" VARCHAR NOT NULL,"forecast_id" VARCHAR,"routing_response_id" VARCHAR,PRIMARY KEY ("tenant_id","snapshot_id"));

CREATE TABLE "eta_snapshot_label" ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"outcome_version_id" VARCHAR NOT NULL,"promise_version_id" VARCHAR NOT NULL,"remaining_duration_seconds" BIGINT,"delay_outcome" BOOLEAN,"label_eligibility" VARCHAR NOT NULL,PRIMARY KEY ("tenant_id","snapshot_id"));

CREATE TABLE "eta_split_assignment" ("tenant_id" VARCHAR NOT NULL,"split_version" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"split_group_id" VARCHAR NOT NULL,"split_role" VARCHAR NOT NULL,"frozen_at" TIMESTAMPTZ NOT NULL,"label_cutoff_at" TIMESTAMPTZ NOT NULL,PRIMARY KEY ("tenant_id","trip_id","split_version"));

CREATE TABLE "eta_history_reference" ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"historical_trip_id" VARCHAR NOT NULL,"historical_outcome_version_id" VARCHAR NOT NULL,"historical_duration_seconds" BIGINT NOT NULL,"historical_label_known_at" TIMESTAMPTZ NOT NULL,"baseline_group" VARCHAR NOT NULL,PRIMARY KEY ("tenant_id","snapshot_id","historical_trip_id"));
